Action: run_sql({'query': 'SELECT e.name, e.address, e.gmap_id, e.slchd_establishment_key, ek.slchd_establishment_key as matched_key,\n       COUNT(i.inspection_id) as inspection_count,\n       MAX(i.inspection_date) as last_inspection_date,\n       AVG(i.inspection_score) as avg_inspection_score\nFROM establishments e\nLEFT JOIN establishment_keys ek ON LOWER(ek.name) LIKE \'%\' || LOWER(SPLIT_PART(e.name, \' \', 1)) || \'%\' \n  AND LOWER(ek.address) LIKE \'%\' || LOWER(SPLIT_PART(e.address, \',\', 1)) || \'%\'\nLEFT JOIN inspections i ON i.slchd_establishment_key = COALESCE(e.slchd_establishment_key, ek.slchd_establishment_key)\nWHERE e.name IN (\'King Buffet\', \'Red Lotus Bistro\', "Charlie Chow\'s Dragon Grill", \'Sozo Kitchen\', \'Mi La-Cai Noodle House\', "P.F. Chang\'s")\nGROUP BY e.name, e.address, e.gmap_id, e.slchd_establishment_key, ek.slchd_establishment_key;'})

