Action: run_sql({'query': "SELECT \n  e.gmap_id,\n  e.name,\n  e.address,\n  e.avg_rating,\n  e.num_of_reviews,\n  COALESCE(e.price, 'N/A') as price_level,\n  e.slchd_establishment_key,\n  STRING_AGG(c.category, ', ') as categories\nFROM establishments e\nJOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nJOIN category c ON ec.category_id = c.category_id\nWHERE LOWER(c.category) LIKE '%chinese%'\nGROUP BY e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key\nORDER BY avg_rating DESC, num_of_reviews DESC;"})

